func (q *Queries) SetAlertLastNotifiedAt(ctx context.Context, arg SetAlertLastNotifiedAtParams) error {
	_, err := q.db.Exec(ctx, setAlertLastNotifiedAt, arg.ID, arg.LastNotifiedAt)
	return err
}

const summarizeAlertsByStatus = `-- name: SummarizeAlertsByStatus :many
SELECT status, severity, count(*) AS total
FROM alerts a
WHERE ($1::uuid[] IS NULL OR a.resource_id = ANY($1::uuid[]))
GROUP BY status, severity
`

type SummarizeAlertsByStatusRow struct {
	Status   string `json:"status"`
	Severity string `json:"severity"`
	Total    int64  `json:"total"`
}

// Dashboard summary (spec §19): counts grouped by status/severity,
// already scoped to the caller's authorized resources.
func (q *Queries) SummarizeAlertsByStatus(ctx context.Context, resourceIds []uuid.UUID) ([]SummarizeAlertsByStatusRow, error) {
	rows, err := q.db.Query(ctx, summarizeAlertsByStatus, resourceIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeAlertsByStatusRow{}
	for rows.Next() {
		var i SummarizeAlertsByStatusRow
		if err := rows.Scan(&i.Status, &i.Severity, &i.Total); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

