const worstActiveAlertSeverityByResource = `-- name: WorstActiveAlertSeverityByResource :many
SELECT resource_id,
    (array_agg(severity ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 WHEN 'WARNING' THEN 1 ELSE 2 END))[1]::text AS worst_severity
FROM alerts
WHERE status IN ('ACTIVE', 'ACKNOWLEDGED')
    AND ($1::uuid[] IS NULL OR resource_id = ANY($1::uuid[]))
GROUP BY resource_id
`

type WorstActiveAlertSeverityByResourceRow struct {
	ResourceID    uuid.UUID `json:"resource_id"`
	WorstSeverity string    `json:"worst_severity"`
}

// Step 19 Phase 2: one row per resource with at least one currently-open
// (ACTIVE/ACKNOWLEDGED) alert -- its worst severity among CRITICAL >
// WARNING > INFO -- feeding MonitoringDashboardHandler's merged DTO's
// ActiveAlertSeverity field and the Resources endpoint's alert_severity
// filter, batched across every resource in the caller's authorized set
// rather than one query per resource. Same nil-vs-set "resource_ids"
// convention as every other cross-resource summary query in this project
// (nil = unrestricted, an Admin's own caller-side guard).
func (q *Queries) WorstActiveAlertSeverityByResource(ctx context.Context, resourceIds []uuid.UUID) ([]WorstActiveAlertSeverityByResourceRow, error) {
	rows, err := q.db.Query(ctx, worstActiveAlertSeverityByResource, resourceIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorstActiveAlertSeverityByResourceRow{}
	for rows.Next() {
		var i WorstActiveAlertSeverityByResourceRow
		if err := rows.Scan(&i.ResourceID, &i.WorstSeverity); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
